\end{proposition}

\item Use this to prove “directly, that $-\deg\det$ induces a valuation on $\vF_q(\phi_T,u)$” and “effectively extend[] to inseparable endomorphisms using integrality.” Concretely, one proves the following theorem.

\begin{theorem}\label{thm:degdetval}
Let $k$ be a finite extension of $\vF_q$.
Let $\phi:\vF_q[T]\longrightarrow k\{\tau\}$ be a Drinfeld module. Let $v\in \End(\phi)$. Then, $\deg\det(v)=\deg_{\tau}(v)$, and therefore $-\deg\det(\cdot)$ induces a valuation on $R=\vF_q[v,T]$ which can be extended to a valuation of $\vF_q(v,T)$.
\end{theorem}

\item “By the independence of valuations, this forces that there is only one place above $\infty\subseteq \vF_q[T]$.” We first use the following lemma.

\begin{lemma}\label{lemma:techsplit}
Let $M$ be an extension of $\vF_q(T)$. If the map $v:y\mapsto v_{\infty}(N(y))$ is a valuation on $M$ then  there is only one place of $M$ lying above $\infty\subseteq \vF_q(T)$.
\end{lemma}

In our setting, this is guaranteed by the following lemma.

\begin{lemma}\label{lemma:uniqueplaceourcase}
Let $\phi:\vF_q[T]\rightarrow k\{\tau\}$ be a Drinfeld module and $u$ be an endomorphism of $\phi$. Set $L=\vF_q(T,u)$. The map $y\mapsto v_{\infty}(N_{L:\vF_q(T)}(y))$ is a valuation.
In particular, there is only one place $\tilde\infty$ of $L$ lying above $\infty$.
\end{lemma}

\item Finally, later the text “puts everything together \`a la Hasse-Weil and proves the special form of the characteristic polynomial of the Frobenius, including the computation of the absolute values of its roots,” yielding (1) and (2).
\end{itemize}
For (3), the text notes: “For simplicity, we compute $(a_0)$ and not $a_0$,” and that “The coefficient of $a_0$ can be obtained using for example the Weil pairing.”

ref_dict.corollaryshiftedstable:
\begin{corollary}[Shifted stable $\mathbb{A}^1$-connectivity theorem]\label{corollaryshiftedstable}
    Let $S$ be a qcqs scheme of valuative dimension $d$, and $n \geqslant 0$ be an integer. Then for any $n$-connective pointed space $E \in \mathcal{P}_{\emph{Nis}}(\emph{Sm}_S)_\ast$, the motivic spectrum $L_{\emph{mot}} E \in \emph{SH}(S)$ is $(n-d)$-connective. 
\end{corollary}

ref_dict.theoremintrounstable:
\begin{theorem}[Shifted unstable $\mathbb{A}^1$-connectivity; see Theorem~\ref{theoremunstableconnectivity}]\label{theoremintrounstable}
    Let $S$ be a qcqs scheme of valuative dimension~$d$, and $n \geqslant 0$ be an integer. Then for any $n$-connective pointed space $E \in \mathcal{P}_{\emph{Nis}}(\emph{Sm}_S)_\ast$, the motivic space $L_{\emph{mot}} E \in \emph{H}(S)_\ast$ is $(n-d)$-connective.
\end{theorem}

ref_dict.corollaryLmotpreserveperverseconnectivit:
\begin{corollary}\label{corollaryLmotpreserveperverseconnectivity}
    Let $S$ be a qcqs scheme. Then for every integer $n \geqslant 0$, the localisation $L_{\emph{mot}} : \mathcal{P}_{\emph{Nis}}(\emph{Sm}_S)_\ast \rightarrow \H(S)_\ast$ preserves perverse $n$-connective objects.
\end{corollary}

ref_dict.corollaryconvergenceslice:
\begin{corollary}[Convergence of the slice filtration]\label{corollaryconvergenceslice}
    Let $S$ be a qcqs scheme of valuative dimension $d$. Then the motivic spectrum $\mathrm{kgl}_S \in \emph{SH}(S)$ is very effective and, for every integer $n \geqslant 0$, the Nisnevich sheaf of spectra $\omega^\infty \emph{Fil}^j_{\emph{slice}} \emph{KGL}_S$ is $(n-d)$-connective. In particular, if $S$ is a qcqs scheme of finite valuative dimension, then the slice filtration $\emph{Fil}^j_{\emph{slice}} \emph{KGL}_S$ is convergent.
\end{corollary}

ref_dict.theoremunstableconnectivity:
\begin{theorem}[Shifted unstable $\A1$-connectivity theorem]\label{theoremunstableconnectivity}
    Let $S$ be a qcqs scheme of valuative dimension $d$, and \hbox{$n \geqslant 0$} be an integer. Then for any $n$-connective pointed space $E \in \mathcal{P}_{\emph{Nis}}(\emph{Sm}_S)_\ast$, the motivic space \hbox{$L_{\emph{mot}}\,E \in \H(S)_\ast$} is \hbox{$(n-d)$}\nobreakdash-connective. 
\end{theorem}

post_theorem_intro_text:
Theorem~\ref{theoremintrounstable} was previously known when $S$ is the spectrum of a field. For perfect fields, this was first proved by Morel \cite[Theorem~5.38]{morel_a1_topology_field} as a consequence of the main results of \cite{morel_a1_topology_field}. More direct proofs, which also hold for non-perfect fields, were later on provided by Asok \cite{asok_unstable_2009} and Ayoub \cite{ayoub_lectures_park_city}. Here, we follow Ayoub's strategy, and adapt it to the case of an arbitrary base scheme $S$. The two main ingredients in doing so are the results of Clausen--Mathew \cite{clausen_hyperdescent_2021} and the presentation lemma over a general base proved in \cite{bouis_beilinson_2025}; see the outline below for more details.

\subsection*{Outline of the proof.}

\vspace{-.4cm}

\[
\scalebox{1.06}{$
\smash{\substack{E\\ n\text{-connective}}}
\;\Longrightarrow\;
\smash{\substack{E\\ \text{perverse }n\text{-connective}}}
\;\underset{\text{Coro.\ 2.6}}{\Longrightarrow}\;
\smash{\substack{L_{\mathrm{mot}}E\\ \text{perverse }n\text{-connective}}}
\;\Longrightarrow\;
\smash{\substack{L_{\mathrm{mot}}E\\ \text{generically }(n-d)\text{-connective}}}
\;\underset{\text{Gersten}}{\Longrightarrow}\;
\smash{\substack{L_{\mathrm{mot}}E\\ (n-d)\text{-connective}}}
$}
\]

In Section~\ref{sectionperverse}, we introduce the notion of perverse $n$-connectivity for pointed spaces, and prove that it is preserved by the motivic localisation functor $L_{\text{mot}}$ from pointed spaces to motivic spaces (Corollary~\ref{corollaryLmotpreserveperverseconnectivity}). In Section~\ref{sectionunstabletheorem}, we use this result to prove the shifted unstable $\mathbb{A}^1$-connectivity theorem (Theorem~\ref{theoremunstableconnectivity}), as well as consequences for stable $\mathbb{A}^1$\nobreakdash-connectivity (Corollary~\ref{corollaryshiftedstable}) and convergence of the slice filtration on homotopy $K$-theory (Corollary~\ref{corollaryconvergenceslice}).

